# -*- coding: utf-8 -*-
from taf.playwright.sbts.facade import Sbts26R3
from taf.playwright.sbts.provider import Provider


def test_provider_defaults_to_sbts26r3():
    assert Provider.provide() is Sbts26R3
    assert Provider.provide("") is Sbts26R3


def test_provider_accepts_sbts_prefix_or_plain_version():
    assert Provider.provide("SBTS26R3") is Sbts26R3
    assert Provider.provide("26R3") is Sbts26R3
    assert Provider.provide("sbts26r3") is Sbts26R3


def test_provider_falls_back_to_default_for_unknown_version():
    assert Provider.provide("SBTS99R9") is Sbts26R3
